def avg_premium(orders):
    big = [o for o in orders if o > 1000]
    return sum(big) / len(big)

print(avg_premium([120, 340, 990]))

def final_price(price, discounts):
    for d in discounts:
        price = max(price - d, 0.0)
    return price

cart = {"keyboard": 45.0}
promo_codes = [10.0, 15.0, 25.0]
print(f"charge: {final_price(cart['keyboard'], promo_codes):.2f}")

