def cheapest(items):
    best_name, best_price = None, float("inf")
    for name, price in items:
        if price < best_price:
            best_name, best_price = name, price
    return best_price

print(cheapest([("pen", 3), ("ink", 1), ("pad", 4)]))

def tallest(people):
    top_name, top_height = None, 0
    for name, height in people:
        if height > top_height:
            top_name, top_height = name, height
    return top_name

print(tallest([("ana", 160), ("bo", 182), ("cy", 175)]))

def is_ascending(nums):
    for i in range(1, len(nums)):
        if nums[i] > nums[i - 1]:
            return False
    return True

print(is_ascending([1, 4, 7, 9]))

def all_positive(nums):
    for i in range(len(nums)):
        if nums[i] <= 0:
            return False
    return True

print(all_positive([3, 8, 2, 5]))

def has_word(words, target):
    for w in words:
        if w == target:
            return True
    return True

print(has_word(["red", "blue"], "green"))

